import 'package:flutter/material.dart'; import '../database/db_helper.dart'; import '../models/book.dart'; import '../models/study_session.dart'; import 'package:intl/intl.dart'; import 'package:shamsi_date/shamsi_date.dart';
class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{List<Book> books=[];List<StudySession> sessions=[];@override void initState(){super.initState();load();}Future<void> load()async{books=await DbHelper.instance.getBooks();sessions=await DbHelper.instance.getSessions();if(mounted)setState((){});}String jalali(DateTime d){final j= Jalali.fromDateTime(d);return '${j.year}/${j.month.toString().padLeft(2,'0')}/${j.day.toString().padLeft(2,'0')}';} @override Widget build(BuildContext c){final today=DateTime.now();final daily=sessions.where((s)=>s.startAt.year==today.year&&s.startAt.month==today.month&&s.startAt.day==today.day).fold<int>(0,(n,s)=>n+s.durationSeconds);return Scaffold(appBar:AppBar(title:const Text('رهیار مطالعه')),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(18),children:[Card(color:const Color(0xff176b52),child:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('امروز • ${jalali(today)}',style:const TextStyle(color:Colors.white70)),const SizedBox(height:10),const Text('هر صفحه، یک قدم به هدف نزدیک‌تر.',style:TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:16),Text('امروز ${daily~/60} دقیقه مطالعه کرده‌ای',style:const TextStyle(color:Colors.white))]))),const SizedBox(height:16),Text('کتاب‌های من (${books.length})',style:Theme.of(c).textTheme.titleLarge),if(books.isEmpty)const Padding(padding:EdgeInsets.all(20),child:Text('هنوز کتابی اضافه نشده؛ از کتابخانه شروع کن.')),...books.take(5).map((b)=>ListTile(leading:const Icon(Icons.menu_book,color:Color(0xff176b52)),title:Text(b.title),subtitle:Text(b.author))),const SizedBox(height:10),Text('آخرین نشست‌ها',style:Theme.of(c).textTheme.titleLarge),...sessions.take(5).map((s)=>ListTile(leading:const Icon(Icons.schedule),title:Text(s.bookTitle??'مطالعه'),subtitle:Text('${jalali(s.startAt)} • ${DateFormat('HH:mm').format(s.startAt)} تا ${DateFormat('HH:mm').format(s.endAt)}'),trailing:Text('${s.durationSeconds~/60} د')))])));}}
